def solution(n: int) -> int:
    # Find smallest lucky year >= n, then return difference
    # Lucky year: at most one non-zero digit
    # Candidates: numbers of form a*10^k (a in 1..9, k>=0)
    # We only need up to 10^9 range; consider k up to 9 (since 9*10^9 > 10^9)
    best = None
    for k in range(10):
        power = 10 ** k
        for a in range(1, 10):
            val = a * power
            if val >= n:
                if best is None or val < best:
                    best = val
    # If somehow not found (shouldn't happen within constraints), fallback 0
    if best is None:
        best = 0
    return best - n

def main():
    import sys
    data = sys.stdin.read().strip()
    if not data:
        return
    n = int(data)
    print(solution(n))
